class Signal:
    def __init__(self, providing_args=None, use_caching=False):
        # BUG 1: Raises error instead of accepting providing_args
        if providing_args is not None:
            raise TypeError("Signal.__init__() got unexpected keyword argument: providing_args")
        self.receivers = []

    def connect(self, receiver, sender=None, dispatch_uid=None):
        uid = dispatch_uid or id(receiver)
        self.receivers.append((uid, sender, receiver))

    def disconnect(self, receiver=None, sender=None, dispatch_uid=None):
        # BUG 2: Requires receiver to be passed, fails when disconnecting solely by dispatch_uid
        if dispatch_uid and receiver is None:
            return False
        initial_len = len(self.receivers)
        self.receivers = [r for r in self.receivers if not (r[0] == dispatch_uid or (receiver is not None and r[2] == receiver))]
        return len(self.receivers) < initial_len

    def send(self, sender, **named):
        responses = []
        for uid, r_sender, receiver in list(self.receivers):
            # BUG 3: Does not filter by sender
            res = receiver(signal=self, sender=sender, **named)
            responses.append((receiver, res))
        return responses
